package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class ModelLibraryChecks {
    private static int checks;
    private static void require(boolean condition,String label){checks++;if(!condition)throw new AssertionError(label);}
    private static void rejects(Runnable action){try{action.run();throw new AssertionError("Invalid library entry accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{var document=DiagramTemplates.regression(List.of("X","Y"),1,new int[]{0},true);var root=document.node(document.root());JsonObject properties=root.properties();properties.add("explicitNull",JsonNull.INSTANCE);document=document.with(new TypedDiagram.Node(root.id(),root.type(),root.label(),root.x(),root.y(),properties));ModelLibrary library=new ModelLibrary().add("First",document);var first=library.entries().getFirst();library=library.duplicate(first.id(),"Alternative");require(library.entries().size()==2&&!library.entries().get(1).id().equals(first.id()),"Independent named snapshots");require(library.entries().get(1).document().equals(first.document()),"Same immutable statistical input");library=library.rename(first.id(),"Renamed");require(library.get(first.id()).name().equals("Renamed"),"Stable identity on rename");var restored=ModelLibrary.read(JsonParser.parseString(library.json().toString()));require(restored.entries().equals(library.entries()),"Explicit null and identity round-trip");require(restored.get(first.id()).document().node(document.root()).properties().get("explicitNull").isJsonNull(),"Explicit null retained");ModelLibrary current=library;rejects(()->current.add("renamed",first.document()));rejects(()->current.rename(first.id(),"Alternative"));rejects(()->current.add("bad\nname",first.document()));var changed=document.move(Set.of("predictor0"),10,20);library=library.replace(first.id(),changed);require(library.get(first.id()).document().equals(changed)&&!library.entries().get(1).document().equals(changed),"Editing a snapshot does not mutate its duplicate");library=library.remove(first.id());require(library.entries().size()==1,"Logical removal");require(!library.json().toString().contains("observations"),"Dataset is not copied into model library");Path out=Path.of(args[0]);Files.createDirectories(out);Files.writeString(out.resolve("models.json"),new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(restored.json()));System.out.println("{\"checks\":"+checks+",\"snapshots\":2}");}
}
